package com.acmecorp.procurement.controller;

import com.acmecorp.procurement.model.Invoice;
import com.acmecorp.procurement.model.UserPrincipal;
import com.acmecorp.procurement.service.InvoiceService;
import com.acmecorp.procurement.service.InvoiceStorageService;
import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import java.util.UUID;

@RestController
@RequestMapping("/api/v1/invoices")
public class InvoiceController {

    private final InvoiceService invoiceService;
    private final InvoiceStorageService invoiceStorageService;

    public InvoiceController(InvoiceService invoiceService, InvoiceStorageService invoiceStorageService) {
        this.invoiceService = invoiceService;
        this.invoiceStorageService = invoiceStorageService;
    }

    @GetMapping("/{invoiceId}/download")
    public ResponseEntity<Resource> downloadInvoicePdf(
            @PathVariable UUID invoiceId,
            @AuthenticationPrincipal UserPrincipal currentUser) {
        Invoice invoice = invoiceService.getInvoiceById(invoiceId);
        if (!invoice.getOrganizationId().equals(currentUser.getOrganizationId())) {
            throw new AccessDeniedException("Access to invoice belonging to another organization is forbidden.");
        }
        Resource pdfResource = invoiceStorageService.loadInvoiceAsPdf(invoiceId);
        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_PDF)
                .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"invoice-" + invoiceId + ".pdf\"")
                .body(pdfResource);
    }
}
